/* Functions to set the elaborated clock id */

void MOD_mkTbLeft::set_clk_0(char const *s)
{
  __clk_handle_0 = bk_get_or_define_clock(sim_hdl, s);
}


/* State dumping routine */
void MOD_mkTbLeft::dump_state(unsigned int indent)
{
  printf("%*s%s:\n", indent, "", inst_name);
  INST_correct.dump_state(indent + 2u);
  INST_cycle.dump_state(indent + 2u);
  INST_randomShift_init.dump_state(indent + 2u);
  INST_randomVal_init.dump_state(indent + 2u);
}


/* VCD dumping routines */

unsigned int MOD_mkTbLeft::dump_VCD_defs(unsigned int levels)
{
  vcd_write_scope_start(sim_hdl, inst_name);
  vcd_num = vcd_reserve_ids(sim_hdl, 9u);
  unsigned int num = vcd_num;
  for (unsigned int clk = 0u; clk < bk_num_clocks(sim_hdl); ++clk)
    vcd_add_clock_def(sim_hdl, this, bk_clock_name(sim_hdl, clk), bk_clock_vcd_num(sim_hdl, clk));
  vcd_write_def(sim_hdl, bk_clock_vcd_num(sim_hdl, __clk_handle_0), "CLK", 1u);
  vcd_write_def(sim_hdl, num++, "RST_N", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "TASK_getRandom___d15", 64u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "cycle_EQ_128___d6", 1u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h658", 64u);
  vcd_set_clock(sim_hdl, num, __clk_handle_0);
  vcd_write_def(sim_hdl, num++, "x__h9597", 32u);
  num = INST_correct.dump_VCD_defs(num);
  num = INST_cycle.dump_VCD_defs(num);
  num = INST_randomShift_init.dump_VCD_defs(num);
  num = INST_randomVal_init.dump_VCD_defs(num);
  vcd_write_scope_end(sim_hdl);
  return num;
}

void MOD_mkTbLeft::dump_VCD(tVCDDumpType dt, unsigned int levels, MOD_mkTbLeft &backing)
{
  vcd_defs(dt, backing);
  vcd_prims(dt, backing);
}

void MOD_mkTbLeft::vcd_defs(tVCDDumpType dt, MOD_mkTbLeft &backing)
{
  unsigned int num = vcd_num;
  if (dt == VCD_DUMP_XS)
  {
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 64u);
    vcd_write_x(sim_hdl, num++, 1u);
    vcd_write_x(sim_hdl, num++, 64u);
    vcd_write_x(sim_hdl, num++, 32u);
  }
  else
    if (dt == VCD_DUMP_CHANGES)
    {
      if ((backing.PORT_RST_N) != PORT_RST_N)
      {
	vcd_write_val(sim_hdl, num, PORT_RST_N, 1u);
	backing.PORT_RST_N = PORT_RST_N;
      }
      ++num;
      if ((backing.DEF_TASK_getRandom___d15) != DEF_TASK_getRandom___d15)
      {
	vcd_write_val(sim_hdl, num, DEF_TASK_getRandom___d15, 64u);
	backing.DEF_TASK_getRandom___d15 = DEF_TASK_getRandom___d15;
      }
      ++num;
      if ((backing.DEF_cycle_EQ_128___d6) != DEF_cycle_EQ_128___d6)
      {
	vcd_write_val(sim_hdl, num, DEF_cycle_EQ_128___d6, 1u);
	backing.DEF_cycle_EQ_128___d6 = DEF_cycle_EQ_128___d6;
      }
      ++num;
      if ((backing.DEF_x__h658) != DEF_x__h658)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h658, 64u);
	backing.DEF_x__h658 = DEF_x__h658;
      }
      ++num;
      if ((backing.DEF_x__h9597) != DEF_x__h9597)
      {
	vcd_write_val(sim_hdl, num, DEF_x__h9597, 32u);
	backing.DEF_x__h9597 = DEF_x__h9597;
      }
      ++num;
    }
    else
    {
      vcd_write_val(sim_hdl, num++, PORT_RST_N, 1u);
      backing.PORT_RST_N = PORT_RST_N;
      vcd_write_val(sim_hdl, num++, DEF_TASK_getRandom___d15, 64u);
      backing.DEF_TASK_getRandom___d15 = DEF_TASK_getRandom___d15;
      vcd_write_val(sim_hdl, num++, DEF_cycle_EQ_128___d6, 1u);
      backing.DEF_cycle_EQ_128___d6 = DEF_cycle_EQ_128___d6;
      vcd_write_val(sim_hdl, num++, DEF_x__h658, 64u);
      backing.DEF_x__h658 = DEF_x__h658;
      vcd_write_val(sim_hdl, num++, DEF_x__h9597, 32u);
      backing.DEF_x__h9597 = DEF_x__h9597;
    }
}

void MOD_mkTbLeft::vcd_prims(tVCDDumpType dt, MOD_mkTbLeft &backing)
{
  INST_correct.dump_VCD(dt, backing.INST_correct);
  INST_cycle.dump_VCD(dt, backing.INST_cycle);
  INST_randomShift_init.dump_VCD(dt, backing.INST_randomShift_init);
  INST_randomVal_init.dump_VCD(dt, backing.INST_randomVal_init);
}
